test('max_content_width_absolute_text_does_not_wrap', () => {
  const config = Yoga.Config.create();

  const root = Yoga.Node.create(config);
  root.setPositionType(PositionType.Absolute);
  root.setWidth(100);
  root.setHeight(100);

  const root_child0 = Yoga.Node.create(config);
  root_child0.setPositionType(PositionType.Absolute);
  root_child0.setWidth("max-content");
  root.insertChild(root_child0, 0);

  const root_child0_child0 = Yoga.Node.create(config);
  root_child0_child0.setFlexDirection(FlexDirection.Row);
  root_child0.insertChild(root_child0_child0, 0);
  root_child0_child0.setMeasureFunc(intrinsicSizeMeasureFunc.bind({text: "Lorem ipsum dolor sit amet", flexDirection: FlexDirection.Row}));
  root.calculateLayout(undefined, undefined, Direction.LTR);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(0);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(260);
  expect(root_child0.getComputedHeight()).toBe(10);

  expect(root_child0_child0.getComputedLeft()).toBe(0);
  expect(root_child0_child0.getComputedTop()).toBe(0);
  expect(root_child0_child0.getComputedWidth()).toBe(260);
  expect(root_child0_child0.getComputedHeight()).toBe(10);

  root.calculateLayout(undefined, undefined, Direction.RTL);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(-160);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(260);
  expect(root_child0.getComputedHeight()).toBe(10);

  expect(root_child0_child0.getComputedLeft()).toBe(0);
  expect(root_child0_child0.getComputedTop()).toBe(0);
  expect(root_child0_child0.getComputedWidth()).toBe(260);
  expect(root_child0_child0.getComputedHeight()).toBe(10);
});
